_UI={'da':('INPUT','OUTPUT','ANVENDELSE','ARBEJDSGANG','Åbn modul','Brugervejledning','Tutorial'),'en':('INPUT','OUTPUT','USE OF RESULTS','TYPICAL WORKFLOW','Open module','User guide','Tutorial'),'sv':('INMATNING','UTDATA','ANVÄNDNING','ARBETSGÅNG','Öppna modul','Användarhandbok','Introduktion'),'nb':('INNDATA','UTDATA','BRUK AV RESULTAT','ARBEIDSFLYT','Åpne modul','Brukerhåndbok','Veiledning'),'de':('EINGABE','AUSGABE','ERGEBNISVERWENDUNG','ARBEITSABLAUF','Modul öffnen','Benutzerhandbuch','Tutorial'),'fr':('ENTRÉE','SORTIE','UTILISATION DES RÉSULTATS','PROCESSUS','Ouvrir le module','Guide utilisateur','Tutoriel')}
_PROSE={
'da':{m:(f'{m} hjælper den professionelle oversætter med at gennemføre en lokal og systematisk sproglig kontrol. Funktionen giver et konkret grundlag for at undersøge tekstens kvalitet, terminologi eller arbejdsproces uden at ændre originaldokumentet.',f'Brugeren vælger de angivne input, følger arbejdsgangen og vurderer hvert resultat i sin sproglige sammenhæng. Fund er indikatorer til menneskelig gennemgang; programmet kan ikke alene afgøre, om en oversættelse er en bekræftet fejl.') for m in [x[0] for x in MODULES]},
'en':{m:(f'{m} supports a systematic local workflow for the part of professional translation review covered by this function. Use it when you need a clear basis for the next editorial decision while retaining control of your documents.',f'A professional user starts with the stated inputs, follows the workflow and evaluates the result in context. The function automates repeatable checks, but it does not replace linguistic judgment or final document review.') for m in [x[0] for x in MODULES]},
'sv':{m:(f'{m} ger ett systematiskt lokalt arbetsflöde för den del av översättningsgranskningen som funktionen stöder. Använd den när du behöver ett tydligt underlag för nästa redaktionella beslut och vill behålla kontrollen över dina dokument.',f'En professionell användare börjar med de angivna indata, följer arbetsflödet och bedömer resultatet i sitt sammanhang. Funktionen automatiserar upprepade kontroller men ersätter inte språklig bedömning eller slutlig granskning.') for m in [x[0] for x in MODULES]},
'nb':{m:(f'{m} gir en systematisk lokal arbeidsflyt for den delen av oversettelsesgjennomgangen som funksjonen støtter. Bruk den når du trenger et tydelig grunnlag for neste redaksjonelle beslutning og vil beholde kontrollen over dokumentene dine.',f'En profesjonell bruker starter med de angitte inndataene, følger arbeidsflyten og vurderer resultatet i sin sammenheng. Funksjonen automatiserer gjentakbare kontroller, men erstatter ikke språklig vurdering eller endelig gjennomgang.') for m in [x[0] for x in MODULES]},
'de':{m:(f'{m} unterstützt einen systematischen lokalen Arbeitsablauf für den Teil der Übersetzungsprüfung, den diese Funktion abdeckt. Verwenden Sie es, wenn Sie eine klare Grundlage für die nächste redaktionelle Entscheidung benötigen und die Kontrolle über Ihre Dokumente behalten möchten.',f'Professionelle Anwender beginnen mit den angegebenen Eingaben, folgen dem Ablauf und beurteilen das Ergebnis im Kontext. Die Funktion automatisiert wiederholbare Prüfungen, ersetzt jedoch weder sprachliches Urteil noch die abschließende Dokumentprüfung.') for m in [x[0] for x in MODULES]},
'fr':{m:(f'{m} propose un flux de travail local et structuré pour la partie de la révision de traduction couverte par cette fonction. Utilisez-le pour disposer d’une base claire pour la prochaine décision éditoriale tout en gardant le contrôle de vos documents.',f'Le professionnel commence avec les entrées indiquées, suit le flux et évalue le résultat dans son contexte. La fonction automatise les contrôles répétitifs, mais ne remplace ni le jugement linguistique ni la vérification finale du document.') for m in [x[0] for x in MODULES]}}

# The two primary locales contain workflow-specific linguistic copy. Other locales
# retain the localized baseline above until reviewed by a native-language editor.
_SPECIFIC_PROSE={
'da': {
'Dashboard': ('Start med et lokalt projekt, vælg brugerfladesprog og kontrollér kilde- og målsprog, før du åbner et værktøj. Overblikket ændrer ikke dokumenter og er et sikkert sted at se, hvilke lokale funktioner der er til rådighed.', 'Resultatet er et tydeligt næste trin i reviewet: et projekt, en scanner eller et lokalt hjælpedokument. Brug overblikket til at holde analyse, filer og sproglige beslutninger adskilt og til altid at vurdere automatiske fund manuelt.'),
'Project Workflow': ('Start med et projekt, dets kilde- og målsprog, arbejdsmapper og kompatible rule packs. Workflowet samler dokumentvalg, regelvalg og scanning omkring den samme projektkonfiguration uden at overskrive manuskriptet.', 'Funktionen producerer et markeret DOCX-dokument, fundrapporter og inventarreferencer. Brug resultaterne til at følge hvert fund tilbage til den valgte regel og kontrollere, om en mulig terminologisk eller sproglig risiko faktisk kræver en rettelse.'),
'Text Marker': ('Start med et DOCX- eller TXT-dokument og en ordliste i TXT, MD eller CSV, og vælg case- og helordsindstillinger. Programmet matcher bogstavelige udtryk, også når et udtryk er delt over Word-runs, og skriver til en separat fil.', 'Outputtet er et nyt DOCX med Word-fremhævning og en CSV-oversigt over anvendte matches. Brug fremhævningerne til redaktionel søgning efter konsekvent terminologi; et match viser kun tekstlig forekomst, ikke en bekræftet oversættelsesfejl.'),
'Translation Risk Scanner': ('Start med et dansk DOCX og en risk-CSV med expression, category, color, severity, explanation, suggestion og enabled. Scanneren finder de angivne bogstavelige udtryk og tager hensyn til ordgrænser, men forstår ikke automatisk kontekst eller betydning.', 'Outputtet er et separat markeret DOCX samt occurrence- og eventuelt summary-CSV. Brug forklaring, kontekst og forslag til at undersøge false friends, misvisende kognater og andre risikoudtryk; markeringen er altid en hypotese til menneskelig vurdering.'),
'Language Interference Scanner': ('Start med et dansk DOCX og en DA-interference-CSV med stabile rule_id, language, category, severity, color, explanation, suggestion og enabled. Reglerne beskriver mulige norsk-danske eller svensk-danske interferenser, ikke sikre fejl.', 'Outputtet er et separat DOCX med RED, ORANGE eller YELLOW-markering samt forekomst- og summary-CSV. Brug fundene til at kontrollere ordvalg, falske venner og kildesproglige former i kontekst; fælles nordiske ord kan være korrekte og må ikke rettes automatisk.'),
'Word Index': ('Start med et DOCX eller TXT, vælg dansk eller norsk bokmål og beslut, om den bundtede stopordsliste skal bruges. Programmet tæller ord og normaliserer kun efter de dokumenterede indeksregler; det fortolker ikke tekstens betydning.', 'Outputtet er en frekvensliste eller CSV/TXT-eksport, der viser gentagne ord og mulige terminologiske mønstre. Brug indekset til at finde inkonsistent ordvalg, overhyppige formuleringer eller mulig kildeinterferens, og kontrollér altid kandidaten i den fulde tekst.'),
'File Inventory': ('Start med lokale filreferencer fra de arbejdsflows, du allerede har kørt. Inventaret gemmer stier og metadata, ikke dokumentindhold, så du kan søge efter tidligere input, rule packs og resultater uden at flytte eller ændre filerne.', 'Outputtet er en søgbar liste, hvor eksisterende filer kan åbnes eller genbruges, mens manglende filer markeres tydeligt. Brug det til sporbarhed og gentagelse af review; en reference er ikke en sikkerhedskopi og kan blive ugyldig, hvis filen flyttes uden for programmet.'),
'Terminology': ('Start med et lokalt SQLite-termbase, et concept og termer med sprog, status, definition og emnefelt. Du kan importere en kundes CSV efter eksplicit kolonnemapping, men programmet antager ikke, at to kolonner udgør samme concept.', 'Outputtet er en søgbar termbase og en canonical UTF-8 CSV med stabile IDs. Brug preferred, admitted, deprecated og forbidden status til at skelne godkendt terminologi fra reviewkandidater; mulige dubletter vises til menneskelig afgørelse og flettes ikke automatisk.'),
'Glossaries & Rules': ('Start med en regel- eller glossary-CSV i det schema, som importdialogen genkender, og vælg sprogpar, kategori og status. Importen validerer headers, IDs og felter, så en DA-interference-regel ikke fejlagtigt bliver behandlet som en Translation Risk-regel.', 'Outputtet er et lokalt, søgbart rule pack, som kan redigeres, eksporteres og knyttes til kompatible projekter. Brug packs til ensartede kontroller, men kontrollér altid sprogspecifikke regler og konflikter før scanning.'),
'Prompt Library': ('Start med en lokal promptskabelon eller Prompt Builderens valg af opgave, sprog, domæne, kriterier og outputstruktur. Programmet sender ingen tekst til en tjeneste; det samler kun en redigerbar instruktion til dit eget reviewarbejde.', 'Outputtet er en gemt eller eksporteret tekstprompt, der skelner mellem observation, mulig problemstilling og bekræftet fejl. Brug prompten som en gentagelig brief, og indsæt aldrig fortroligt materiale i eksterne værktøjer uden selv at kontrollere deres behandling.'),
'Settings': ('Start med lokale præferencer: UI-sprog, projekt, source/target language og arbejdsmapper. Indstillingerne styrer visningen og den valgte arbejdskontekst, men ændrer ikke kildedokumentets tekst eller automatisk udleder regler af et sprogpar.', 'Outputtet er en gemt lokal konfiguration, som gør gentagne reviewkørsler ensartede. Brug den til at kontrollere, at scanner, termbase og rapportmapper passer til den aktuelle opgave, før du behandler et dokument.'),
'Help': ('Start med det modul eller den proces, du vil forstå, og åbn den relevante offline-sektion. Hjælpen beskriver faktiske inputformater, rule schemas, output og begrænsninger, så du kan forberede en fil uden at gætte på kolonnenavne.', 'Outputtet er en lokal procedure og eventuelt en tutorial med bundtede eksempler. Brug teksten til at tolke markerede fund som reviewsignaler og til at dokumentere din beslutning; hjælpen erstatter ikke sproglig eller Microsoft Word-baseret slutkontrol.')},
'en': {
'Dashboard': ('Start with a local project and review the available language and document tools before opening a workflow. The dashboard changes no manuscript content; it is the controlled entry point for selecting a project and a linguistic task.', 'The output is a clear next action rather than a document transformation. Use it to keep project setup, language decisions and review operations separate, and assess all automated evidence as a human reviewer.'),
'Project Workflow': ('Start with a project, source and target languages, working folders and compatible rule packs. The workflow combines document selection, rule selection and scanning under one saved configuration without overwriting the source.', 'It produces a marked DOCX, occurrence reports and inventory references. Use each finding to trace back to its rule and decide whether the possible terminology or language risk warrants a correction.'),
'Text Marker': ('Start with DOCX or TXT and a TXT, MD or CSV expression list, then choose case and whole-word settings. Literal expressions are matched across split Word runs where safe and written to a separate output document.', 'The result is a new DOCX with Word highlighting and a CSV of applied matches. Use it for editorial terminology searches; a match proves occurrence, not a translation error.'),
'Translation Risk Scanner': ('Start with a DOCX and a risk CSV containing expression, category, color, severity, explanation, suggestion and enabled. The scanner finds configured literal risks using word boundaries, but it cannot infer meaning or context.', 'The result is a separate marked DOCX and occurrence/optional summary CSV. Review context and explanations for false friends and misleading cognates; every finding is a review hypothesis, never a confirmed error.'),
'Language Interference Scanner': ('Start with a DOCX and the strict DA-interference CSV containing stable rule IDs, language, category, severity, color, explanation, suggestion and enabled. Rules describe possible Danish/Norwegian/Swedish interference rather than certain mistakes.', 'The result is a separate DOCX with RED, ORANGE or YELLOW marking plus occurrence and summary CSV. Shared Nordic words may be correct, so verify each candidate in context before changing it.'),
'Word Index': ('Start with DOCX or TXT, select Danish or Norwegian Bokmål and choose whether bundled stopwords should be excluded. The index counts words according to its documented rules; it does not interpret linguistic meaning.', 'The output is a frequency list or CSV/TXT export revealing repeated terms and possible terminology patterns. Use it to investigate inconsistent wording or interference candidates in the full text.'),
'File Inventory': ('Start with local file references created by your review workflows. The inventory stores paths and metadata, not document contents, so prior inputs, rule packs and outputs can be found without moving or editing them.', 'The result is a searchable list that opens or reuses existing files and flags missing paths. Use it for traceability and repeatability; it is not a backup.'),
'Terminology': ('Start with a local SQLite termbase, a concept and terms carrying language, status, definition and subject data. Customer CSV import requires explicit mapping; two bilingual cells are never silently treated as one concept.', 'The result is a searchable termbase and canonical UTF-8 CSV with stable IDs. Use statuses to distinguish approved terms from review candidates; possible duplicates are shown for human decisions.'),
'Glossaries & Rules': ('Start with a recognized glossary or rule CSV and choose its language pair, category and status. Import validation checks headers and IDs so a DA-interference file is not silently interpreted as a Translation Risk file.', 'The result is a local searchable rule pack that can be edited, exported and assigned to compatible projects. Review language-specific conflicts before scanning.'),
'Prompt Library': ('Start with a local template or use Prompt Builder to select task, languages, domain, criteria and output structure. No text is sent to a service; the application only creates an editable local instruction.', 'The result is a saved or exported prompt separating observations, possible problems and confirmed errors. Use it as a repeatable review brief and protect confidential material.'),
'Settings': ('Start with local preferences for UI language, project, source/target language and working folders. Settings control presentation and context; they do not alter source text or invent rules for a language pair.', 'The result is a saved local configuration for repeatable reviews. Use it to confirm scanner, termbase and report locations before processing a document.'),
'Help': ('Start with the module or procedure you need to understand and open its offline section. The guide documents actual inputs, schemas, outputs and limitations so file preparation does not depend on guessing column names.', 'The result is a local procedure or tutorial with bundled examples. Use it to interpret markings as review signals and document decisions; it does not replace linguistic or Microsoft Word acceptance review.')}}

class ModuleIntroduction(QWidget):
    def __init__(self,module,locale='da',open_callback=None,parent=None):
        super().__init__(parent); self.module=module; self.help_id=dict(MODULES)[module]; self.locale=locale; self.open_callback=open_callback; self.guide=QPushButton(); self.tutorial=QPushButton(); self.open=QPushButton(); self.open.setProperty('help_id',self.help_id); self.guide.setProperty('help_id',self.help_id); self.refresh(locale)
        self.open.clicked.connect(lambda: self.open_callback() if self.open_callback else None); self.guide.clicked.connect(self.open_guide); self.tutorial.clicked.connect(self.open_tutorial)
    def refresh(self,locale):
        self.locale=locale; text=_TEXT.get(locale,_TEXT['en']).get(self.module,_TEXT['en'][self.module]); labels=_UI.get(locale,_UI['en']); self.open.setText(labels[4]); self.guide.setText(labels[5]); self.tutorial.setText(labels[6]); layout=QVBoxLayout(self); layout.setSpacing(8)
        title=QLabel(text[0]); title.setStyleSheet('font-size:20px;font-weight:bold'); layout.addWidget(title); layout.addWidget(QLabel(text[1])); p1,p2=_SPECIFIC_PROSE.get(locale,_PROSE).get(locale,_PROSE['en'])[self.module]; first=QLabel(p1); second=QLabel(p2); first.setWordWrap(True); second.setWordWrap(True); layout.addWidget(first); layout.addWidget(second); box=QGroupBox(labels[3]); form=QFormLayout(box); form.addRow(labels[0],QLabel(text[2])); form.addRow(labels[1],QLabel(text[3])); form.addRow(labels[2],QLabel(text[4])); form.addRow(labels[3],QLabel(text[5])); layout.addWidget(box); layout.addWidget(self.open); layout.addWidget(self.guide)
        if self.module in ('Dashboard','Project Workflow','Terminology','Help'): layout.addWidget(self.tutorial)
        layout.addStretch(); self.setLayout(layout)
    def open_guide(self):
        root=Path(getattr(sys,'_MEIPASS',Path(__file__).resolve().parents[3])); QDesktopServices.openUrl(QUrl.fromLocalFile(str(root/'docs'/'manual'/'help.html')+'#'+self.help_id))
    def open_tutorial(self):
        root=Path(getattr(sys,'_MEIPASS',Path(__file__).resolve().parents[3])); QDesktopServices.openUrl(QUrl.fromLocalFile(str(root/'docs'/'manual'/'help.html')+'#tutorial.overview'))
